custom_fields.clock:
[[[
  var ts = Date.now();
  if (!window._mp_clock_ts || ts - window._mp_clock_ts > 30000) {
    window._mp_clock_ts = ts;
    const d = new Date();
    const h = String(d.getHours()).padStart(2, '0');
    const m = String(d.getMinutes()).padStart(2, '0');
    window._mp_clock_html = '<div class="home-clock">' + h + ':' + m + '</div>';
  }
  return window._mp_clock_html;
]]]

custom_fields.date:
[[[
  var ts = Date.now();
  if (!window._mp_date_ts || ts - window._mp_date_ts > 30000) {
    window._mp_date_ts = ts;
    const d = new Date();
    const wr = d.toLocaleDateString('da-DK', { weekday: 'long' });
    const mr = d.toLocaleDateString('da-DK', { month: 'long' });
    const wd = wr.charAt(0).toUpperCase() + wr.slice(1);
    window._mp_date_html = '<div class="home-date">' + wd + ' d. ' + d.getDate() + '. ' + mr + '</div>';
  }
  return window._mp_date_html;
]]]

