custom_fields.current_weather:
[[[
  var tempSensor = states['sensor.udendors_temperatur'];
  var weather = states['weather.forecast_home'];
  var temp = null;

  if (
    tempSensor &&
    tempSensor.state !== 'unknown' &&
    tempSensor.state !== 'unavailable' &&
    !isNaN(Number(tempSensor.state))
  ) {
    temp = Number(tempSensor.state).toLocaleString('da-DK', {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1
    });
  } else if (
    weather &&
    weather.attributes &&
    weather.attributes.temperature !== undefined &&
    !isNaN(Number(weather.attributes.temperature))
  ) {
    temp = Number(weather.attributes.temperature).toLocaleString('da-DK', {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1
    });
  }

  var weatherMap = {
    'clear-night': 'klart',
    cloudy: 'skyet',
    exceptional: 'ekstremt',
    fog: 't\u00e5ge',
    hail: 'hagl',
    lightning: 'lyn',
    'lightning-rainy': 'tordenregn',
    partlycloudy: 'delvist skyet',
    pouring: 'kraftig regn',
    rainy: 'regn',
    snowy: 'sne',
    'snowy-rainy': 'slud',
    sunny: 'sol',
    windy: 'bl\u00e6sende',
    'windy-variant': 'bl\u00e6sende'
  };

  var conditionRaw = weather ? weather.state : '';
  var condition = weatherMap[conditionRaw] || conditionRaw || '';
  var tempText = temp !== null ? temp + '\u00B0' : '--\u00B0';

  return '<span style="display:inline-flex;align-items:center;vertical-align:middle;white-space:nowrap;">' +
    '<span style="font-size:30px;font-weight:800;color:#F4F6F2;">' + tempText + '</span>' +
    '<span style="font-size:30px;font-weight:600;color:rgba(244,246,242,0.42);margin:0 10px;">|</span>' +
    '<span style="font-size:30px;font-weight:800;color:#F4F6F2;">' + condition + '</span>' +
    '</span>';
]]]

card.icon:
[[[
  var weather = states['weather.forecast_home'];
  var condition = weather ? weather.state : '';
  var iconMap = {
    'clear-night': 'mdi:weather-night',
    cloudy: 'mdi:weather-cloudy',
    exceptional: 'mdi:weather-tornado',
    fog: 'mdi:weather-fog',
    hail: 'mdi:weather-hail',
    lightning: 'mdi:weather-lightning',
    'lightning-rainy': 'mdi:weather-lightning-rainy',
    partlycloudy: 'mdi:weather-partly-cloudy',
    pouring: 'mdi:weather-pouring',
    rainy: 'mdi:weather-rainy',
    snowy: 'mdi:weather-snowy',
