card.name:
[[[
  const e = states['sensor.opvaskemaskine_current_program_remaining_time'];
  const v = Number(e?.state);

  if (
    !e ||
    e.state === 'unknown' ||
    e.state === 'unavailable' ||
    isNaN(v) ||
    v <= 0
  ) {
    return '';
  }

  const minutes = Math.round(v);
  return `Opvask kører | ${minutes} min. tilbage`;
]]]

card.display:
[[[
