custom_fields.idle_return:
[[[
  if (!window.minipanelIdleReturnInstalled) {
    window.minipanelIdleReturnInstalled = true;

    const timeout = 60000;
    const returnPath = '/dashboard-minipanel/home';

    let timer;

    const resetTimer = () => {
      clearTimeout(timer);

      timer = setTimeout(() => {
        const path = window.location.pathname;
        const search = window.location.search || '';

        if (
          path.startsWith('/dashboard-minipanel') &&
          !search.includes('disable_km') &&
          path !== '/dashboard-minipanel/home'
        ) {
          history.pushState(null, '', returnPath);
          window.dispatchEvent(new Event('location-changed'));
        }
      }, timeout);
    };

    ['click', 'touchstart', 'mousemove', 'keydown'].forEach(eventName => {
      document.addEventListener(eventName, resetTimer, true);
    });

    resetTimer();
  }

  return '';
]]]

custom_fields.main:
[[[
  const entityId = 'light.stue_lights';
  const e = states[entityId];
  if (!e) return '<div class="room-head"><div class="room-icon"><ha-icon icon="mdi:alert"></ha-icon></div><div class="room-copy"><div class="room-name">Stue</div><div class="room-state">Mangler</div></div></div>';

  const expand = (id, s = new Set()) => {
    if (s.has(id)) return [];
    s.add(id);
    const m = states[id]?.attributes?.entity_id;
    return Array.isArray(m) && m.length ? m.flatMap(x => expand(x, s)) : [id];
  };

  const members = expand(entityId);
  const total = members.length || 1;
  const onCount = members.filter(id => states[id]?.state === 'on').length;
  const on = onCount > 0;
  const b = Number(e.attributes?.brightness);
  const pct = Number.isFinite(b) && on ? Math.round((b / 255) * 100) : 0;
  const status = !on ? 'Slukket' : total > 1 ? `${onCount} af ${total} tændt` : Number.isFinite(b) ? `Tændt · ${pct} %` : 'Tændt';

  return `<div class="room-head"><div class="room-icon ${on ? 'on' : ''}"><ha-icon icon="mdi:sofa-outline"></ha-icon></div><div class="room-copy"><div class="room-name">Stue</div><div class="room-state">${status}</div></div></div>`;
]]]

custom_fields.switch:
[[[
  const on = states['light.stue_lights']?.state === 'on';
  return `<div class="room-toggle ${on ? 'on' : 'off'}"><div class="room-toggle-knob"></div></div>`;
]]]

