custom_fields.toggle:
[[[
  const groups = [
    'light.stue_lights',
    'light.kokken_lights',
    'light.kokken_lys_niche',
    'light.kokken_kokken_daemper',
    'light.overskabe',
    'light.hylder'
  ];

  const expand = (id, seen = new Set()) => {
    if (seen.has(id)) return [];
    seen.add(id);

    const s = states[id];
    if (!s) return [];

    const members = s.attributes?.entity_id;
    if (Array.isArray(members) && members.length > 0) {
      return members.flatMap(mid => expand(mid, seen));
    }

    return [id];
  };

  const anyOn = groups
    .flatMap(id => expand(id))
    .some(id => states[id]?.state === 'on');

  return `
    <div class="master-switch ${anyOn ? 'on' : 'off'}">
      <div class="master-knob"></div>
    </div>
  `;
]]]

