custom_fields.idle_return:
[[[
  if (!window.minipanelIdleReturnInstalled) {
    window.minipanelIdleReturnInstalled = true;

    const timeout = 60000;
    const returnPath = '/dashboard-minipanel/home';

    let timer;

    const resetTimer = () => {
      clearTimeout(timer);

      timer = setTimeout(() => {
        const path = window.location.pathname;
        const search = window.location.search || '';

        if (
          path.startsWith('/dashboard-minipanel') &&
          !search.includes('disable_km') &&
          path !== '/dashboard-minipanel/home'
        ) {
          history.pushState(null, '', returnPath);
          window.dispatchEvent(new Event('location-changed'));
        }
      }, timeout);
    };

    ['click', 'touchstart', 'mousemove', 'keydown'].forEach(eventName => {
      document.addEventListener(eventName, resetTimer, true);
    });

    resetTimer();
  }

  return '';
]]]

custom_fields.body:
[[[
  const remaining = states['sensor.opvaskemaskine_current_program_remaining_time'];
  const door = states['binary_sensor.opvaskemaskine_door'];
  const autoDose = states['binary_sensor.opvaskemaskine_auto_dose_refill'];
  const rinse = states['binary_sensor.opvaskemaskine_rinse_aid_refill'];
  const salt = states['binary_sensor.opvaskemaskine_salt_refill'];

  const doorOpen = door?.state === 'on';

  let running = false;
  let remainingText = 'Ingen aktiv tid';

  if (
    remaining &&
    remaining.state !== 'unknown' &&
    remaining.state !== 'unavailable' &&
    !isNaN(Number(remaining.state)) &&
    Number(remaining.state) > 0
  ) {
    running = true;
    const minutes = Math.round(Number(remaining.state));
    remainingText = `Kører · ${minutes} ${minutes === 1 ? 'minut' : 'minutter'} tilbage`;
  }

  const refill = (e) => {
    if (!e || e.state === 'unknown' || e.state === 'unavailable') return 'Ukendt';
    return e.state === 'on' ? 'Mangler' : 'OK';
  };

  const problem =
    doorOpen ||
    autoDose?.state === 'on' ||
    rinse?.state === 'on' ||
    salt?.state === 'on';

  const iconClass = problem ? 'warn' : running ? 'active' : '';

  return `
    <div class="card-head">
      <div class="device-icon ${iconClass}">
        <ha-icon icon="mdi:dishwasher"></ha-icon>
      </div>

      <div class="head-text">
        <div class="device-title">Opvask</div>
        <div class="device-sub">${remainingText}</div>
      </div>

      ${running ? `<div class="run-badge"><span></span>KØRER</div>` : ``}
    </div>

    <div class="door-pill">
      <span>Dør</span>
      <strong class="${doorOpen ? 'bad' : 'good'}">${doorOpen ? 'Åben' : 'Lukket'}</strong>
    </div>

    <div class="mini-grid">
      <div class="mini-pill">
        <span>Vaske-gel</span>
        <strong class="${autoDose?.state === 'on' ? 'bad' : 'good'}">${refill(autoDose)}</strong>
      </div>
      <div class="mini-pill">
        <span>Afspænd.</span>
        <strong class="${rinse?.state === 'on' ? 'bad' : 'good'}">${refill(rinse)}</strong>
      </div>
      <div class="mini-pill">
        <span>Salt</span>
        <strong class="${salt?.state === 'on' ? 'bad' : 'good'}">${refill(salt)}</strong>
      </div>
    </div>
  `;
]]]

