custom_fields.body:
[[[
  const r = states['sensor.running_status'];
  const raw = r?.state || 'unknown';

  const stateMap = {
    cleaning: 'Rengør',
    running: 'Rengør',
    paused: 'Pauset',
    standby: 'Standby',
    charging: 'Oplader',
    docked: 'Docked',
    sleeping: 'Sover',
    idle: 'Klar',
    unknown: 'Ukendt',
    unavailable: 'Utilgængelig'
  };

  const label = stateMap[raw] || raw;
  const active = ['cleaning', 'running'].includes(raw);
  const bad = ['unknown', 'unavailable'].includes(raw);

  return `
    <div class="robot-row">
      <div class="robot-icon ${active ? 'active' : bad ? 'off' : ''}">
        <ha-icon icon="mdi:robot-vacuum"></ha-icon>
      </div>
      <div class="robot-text">
        <div class="robot-title">Eufy S1 Pro</div>
        <div class="robot-sub">${label}</div>
      </div>
    </div>
  `;
]]]

custom_fields.toggle:
[[[
  const v = states['vacuum.eufy_robovac_s1_pro'];
  const r = states['sensor.running_status'];
  const vs = v?.state || '';
  const rs = r?.state || '';
  const active = vs === 'cleaning' || vs === 'returning' || rs === 'cleaning' || rs === 'running';
  return `<div class="vac-toggle ${active ? 'on' : 'off'}"><div class="vac-knob"></div></div>`;
]]]

