.light-toggle.on .light-toggle-knob{left:28px}

custom_fields.toggle:
[[[
  const groups = ['light.kontor_lights', 'light.badevaerelse_light', 'light.sovevaerelse_lights', 'light.caroline_lights', 'light.garderobe', 'light.kokken_lights', 'light.kokken_lys_niche', 'light.kokken_kokken_daemper', 'light.overskabe', 'light.hylder', 'light.stue_lights', 'light.nedenunder', 'light.ovenpa'];
  const anyOn = groups.some(id => states[id]?.state === 'on');
  return `<div class="master-switch ${anyOn ? 'on' : 'off'}"><div class="master-knob"></div></div>`;
]]]

tap_action.service:
[[[
  const groups = ['light.kontor_lights', 'light.badevaerelse_light', 'light.sovevaerelse_lights', 'light.caroline_lights', 'light.garderobe', 'light.kokken_lights', 'light.kokken_lys_niche', 'light.kokken_kokken_daemper', 'light.overskabe', 'light.hylder', 'light.stue_lights', 'light.nedenunder', 'light.ovenpa'];
  const anyOn = groups.some(id => states[id]?.state === 'on');
  return anyOn ? 'light.turn_off' : 'light.turn_on';
]]]
